# Generated by Trae Work
"""
UNISON VAE — 1D 梅尔频谱变分自编码器

基于 ResNet 风格的 1D 卷积 VAE，在梅尔频谱域操作。
输入为 80 维 (16kHz) 或 128 维 (44kHz) 梅尔谱，输出 20/40 维潜在表示。

特点:
- 1D 卷积架构 (Encoder1D / Decoder1D)
- 中间层自注意力 (AttnBlock1D)
- 残差块 + 下采样/上采样
- 学习式增益 (learnable_gain) 控制输出幅度
- 激活裁剪 (clip_act=256) 稳定训练
- 数据归一化 (precomputed mean/std)

参考文件:
- mmaudio/ext/autoencoder/vae.py
- mmaudio/ext/autoencoder/vae_modules.py
- mmaudio/ext/autoencoder/autoencoder.py
- mmaudio/ext/autoencoder/distributions.py
"""

from typing import Optional
import torch
import torch.nn as nn
import torch.nn.functional as F


# ============================================================
# 分布：对角高斯后验
# ============================================================

class DiagonalGaussianDistribution(nn.Module):
    """
    对角高斯分布，用于 VAE 瓶颈。
    输入: moments [B, 2*C, T]，前 C 维是 mean，后 C 维是 logvar
    """
    def __init__(self, parameters: torch.Tensor, deterministic: bool = False):
        super().__init__()
        self.parameters = parameters
        self.mean, self.logvar = torch.chunk(parameters, 2, dim=1)
        self.logvar = torch.clamp(self.logvar, -30.0, 20.0)
        self.deterministic = deterministic
        self.std = torch.exp(0.5 * self.logvar)
        self.var = torch.exp(self.logvar)
        if self.deterministic:
            self.var = self.std = torch.zeros_like(
                self.mean, device=self.parameters.device, dtype=self.parameters.dtype
            )

    def sample(self, rng: Optional[torch.Generator] = None) -> torch.Tensor:
        """重参数化采样: z = mean + std * ε"""
        sample = torch.randn(self.mean.shape, generator=rng,
                             device=self.parameters.device, dtype=self.parameters.dtype)
        x = self.mean + self.std * sample
        return x

    def kl(self, other: Optional["DiagonalGaussianDistribution"] = None) -> torch.Tensor:
        """KL 散度: D_KL(N(μ,σ²) || N(0,1)) 或 D_KL(N(μ1,σ1²) || N(μ2,σ2²))"""
        if self.deterministic:
            return torch.Tensor([0.0])
        else:
            if other is None:
                return 0.5 * torch.sum(
                    torch.pow(self.mean, 2) + self.var - 1.0 - self.logvar,
                    dim=[1, 2]
                )
            else:
                return 0.5 * torch.sum(
                    torch.pow(self.mean - other.mean, 2) / other.var
                    + self.var / other.var - 1.0 - self.logvar + other.logvar,
                    dim=[1, 2]
                )

    def nll(self, sample: torch.Tensor, dims: list[int] = [1, 2, 3]) -> torch.Tensor:
        """负对数似然"""
        if self.deterministic:
            return torch.Tensor([0.0])
        logtwopi = torch.log(2.0 * torch.pi)
        return 0.5 * torch.sum(
            logtwopi + self.logvar + torch.pow(sample - self.mean, 2) / self.var,
            dim=dims
        )

    def mode(self) -> torch.Tensor:
        """分布模式 = mean"""
        return self.mean


# ============================================================
# 非线性激活
# ============================================================

def nonlinearity(x: torch.Tensor) -> torch.Tensor:
    """Swish / SiLU 激活"""
    return x * torch.sigmoid(x)


def Normalize(in_channels: int, num_groups: int = 32) -> nn.GroupNorm:
    """GroupNorm (默认 32 组)"""
    return nn.GroupNorm(
        num_groups=num_groups, num_channels=in_channels, eps=1e-6, affine=True
    )


# ============================================================
# 1D 残差块
# ============================================================

class ResnetBlock1D(nn.Module):
    """
    1D 残差块 (ResNet 风格)。
    两个 3x1 卷积 + GroupNorm + 非线性激活，可选短接投影。
    """
    def __init__(
        self,
        *,
        in_dim: int,
        out_dim: Optional[int] = None,
        conv_shortcut: bool = False,
        dropout: float = 0.0,
        temb_channels: int = 512,
        kernel_size: int = 3,
        use_norm: bool = True
    ):
        super().__init__()
        self.in_dim = in_dim
        out_dim = in_dim if out_dim is None else out_dim
        self.out_dim = out_dim
        self.use_norm = use_norm

        if use_norm:
            self.norm1 = Normalize(in_dim)
        self.conv1 = nn.Conv1d(in_dim, out_dim, kernel_size=kernel_size,
                               stride=1, padding=kernel_size // 2)
        if temb_channels > 0:
            self.temb_proj = nn.Linear(temb_channels, out_dim)
        if use_norm:
            self.norm2 = Normalize(out_dim)
        self.dropout = nn.Dropout(dropout)
        self.conv2 = nn.Conv1d(out_dim, out_dim, kernel_size=kernel_size,
                               stride=1, padding=kernel_size // 2)
        if in_dim != out_dim:
            if conv_shortcut:
                self.shortcut = nn.Conv1d(in_dim, out_dim, kernel_size=1)
            else:
                self.shortcut = nn.Conv1d(in_dim, out_dim, kernel_size=1)  # NinN
        else:
            self.shortcut = None

    def forward(self, x: torch.Tensor, temb: Optional[torch.Tensor] = None) -> torch.Tensor:
        h = x
        if self.use_norm:
            h = self.norm1(h)
        h = nonlinearity(h)
        h = self.conv1(h)

        if temb is not None:
            h = h + self.temb_proj(nonlinearity(temb))[:, :, None]

        if self.use_norm:
            h = self.norm2(h)
        h = nonlinearity(h)
        h = self.dropout(h)
        h = self.conv2(h)

        if self.shortcut is not None:
            x = self.shortcut(x)

        return x + h


# ============================================================
# 1D 自注意力块
# ============================================================

class AttnBlock1D(nn.Module):
    """
    1D 自注意力块 (全注意力，非局部)。
    类似于 Stable Diffusion 中的注意力块，但在 1D 上操作。
    """
    def __init__(self, in_channels: int):
        super().__init__()
        self.in_channels = in_channels

        self.norm = Normalize(in_channels)
        self.q = nn.Conv1d(in_channels, in_channels, kernel_size=1)
        self.k = nn.Conv1d(in_channels, in_channels, kernel_size=1)
        self.v = nn.Conv1d(in_channels, in_channels, kernel_size=1)
        self.proj_out = nn.Conv1d(in_channels, in_channels, kernel_size=1)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        h_ = self.norm(x)
        q = self.q(h_)
        k = self.k(h_)
        v = self.v(h_)

        # 计算注意力
        B, C, L = q.shape
        q = q.permute(0, 2, 1)            # [B, L, C]
        w_ = torch.bmm(q, k)              # [B, L, L]
        w_ = w_ * (int(C) ** (-0.5))
        w_ = F.softmax(w_, dim=2)

        # 乘 value
        w_ = w_.permute(0, 2, 1)
        h_ = torch.bmm(v, w_)             # [B, C, L]
        h_ = self.proj_out(h_)

        return x + h_


# ============================================================
# 下采样 / 上采样
# ============================================================

class Downsample1D(nn.Module):
    """下采样 (2x stride)，可选带卷积"""
    def __init__(self, in_channels: int, resample_with_conv: bool = True):
        super().__init__()
        self.in_channels = in_channels
        if resample_with_conv:
            self.conv = nn.Conv1d(in_channels, in_channels, kernel_size=3, stride=2, padding=1)
        else:
            self.conv = None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.conv is not None:
            return self.conv(x)
        else:
            return F.avg_pool1d(x, kernel_size=2, stride=2)


class Upsample1D(nn.Module):
    """上采样 (2x)，可选带卷积"""
    def __init__(self, in_channels: int, resample_with_conv: bool = True):
        super().__init__()
        self.in_channels = in_channels
        if resample_with_conv:
            self.conv = nn.Conv1d(in_channels, in_channels, kernel_size=3, stride=1, padding=1)
        else:
            self.conv = None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = F.interpolate(x, scale_factor=2.0, mode="nearest")
        if self.conv is not None:
            x = self.conv(x)
        return x


