class VAE(nn.Module):
    """
    1D 梅尔频谱 VAE。

    架构:
        输入梅尔谱 [B, data_dim, T_mel]
            ↓ Encoder (多层残差块 + 下采样 + 中间注意力)
        moments [B, 2*embed_dim, T_lat]
            ↓ DiagonalGaussianDistribution (重参数化)
        z [B, embed_dim, T_lat]
            ↓ Decoder (多层残差块 + 上采样 + 中间注意力)
        重建梅尔谱 [B, data_dim, T_mel]

    16k 配置: data_dim=80, embed_dim=20, hidden_dim=384
    44k 配置: data_dim=128, embed_dim=40, hidden_dim=512
    """
    def __init__(
        self,
        *,
        data_dim: int,
        embed_dim: int,
        hidden_dim: int,
    ):
        super().__init__()

        # 数据归一化参数 (buffer，不参与训练)
        if data_dim == 80:
            self.data_mean = nn.Buffer(torch.tensor(DATA_MEAN_80D, dtype=torch.float32))
            self.data_std = nn.Buffer(torch.tensor(DATA_STD_80D, dtype=torch.float32))
        elif data_dim == 128:
            # 128 维也有预计算的 mean/std (此处省略完整列表)
            self.data_mean = nn.Buffer(torch.zeros(data_dim, dtype=torch.float32))
            self.data_std = nn.Buffer(torch.ones(data_dim, dtype=torch.float32))

        self.data_mean = self.data_mean.view(1, -1, 1)
        self.data_std = self.data_std.view(1, -1, 1)

        self.encoder = Encoder1D(
            dim=hidden_dim,
            ch_mult=(1, 2, 4),
            num_res_blocks=2,
            attn_layers=[3],
            down_layers=[0],
            in_dim=data_dim,
            embed_dim=embed_dim,
        )
        self.decoder = Decoder1D(
            dim=hidden_dim,
            ch_mult=(1, 2, 4),
            num_res_blocks=2,
            attn_layers=[3],
            down_layers=[0],
            in_dim=data_dim,
            out_dim=data_dim,
            embed_dim=embed_dim,
        )

        self.embed_dim = embed_dim

    def encode(self, x: torch.Tensor, normalize: bool = True) -> DiagonalGaussianDistribution:
        """编码: 梅尔谱 → 高斯后验"""
        if normalize:
            x = self.normalize(x)
        moments = self.encoder(x)
        posterior = DiagonalGaussianDistribution(moments)
        return posterior

    def decode(self, z: torch.Tensor, unnormalize: bool = True) -> torch.Tensor:
        """解码: 潜在表示 → 重建梅尔谱"""
        dec = self.decoder(z)
        if unnormalize:
            dec = self.unnormalize(dec)
        return dec

    def normalize(self, x: torch.Tensor) -> torch.Tensor:
        return (x - self.data_mean) / self.data_std

    def unnormalize(self, x: torch.Tensor) -> torch.Tensor:
        return x * self.data_std + self.data_mean

    def forward(
        self,
        x: torch.Tensor,
        sample_posterior: bool = True,
        rng: Optional[torch.Generator] = None,
        normalize: bool = True,
        unnormalize: bool = True,
    ) -> tuple[torch.Tensor, DiagonalGaussianDistribution]:
        posterior = self.encode(x, normalize=normalize)
        if sample_posterior:
            z = posterior.sample(rng)
        else:
            z = posterior.mode()
        dec = self.decode(z, unnormalize=unnormalize)
        return dec, posterior

    @property
    def device(self) -> torch.device:
        return next(self.parameters()).device

    def get_last_layer(self):
        return self.decoder.conv_out.weight

    def remove_weight_norm(self):
        """移除所有 MPConv1D 的权重归一化"""
        for m in self.modules():
            if hasattr(m, 'remove_weight_norm') and isinstance(m, nn.Conv1d):
                try:
                    nn.utils.remove_weight_norm(m)
                except:
                    pass
        return self


# ============================================================
# 编码器
# ============================================================

class Encoder1D(nn.Module):
    """
    1D VAE 编码器。

    结构:
        conv_in → [Level 0: ResBlock×2 → Attn → Downsample]
                 → [Level 1: ResBlock×2]
                 → [Level 2: ResBlock×2 → Attn]
                 → mid: ResBlock → Attn → ResBlock
                 → conv_out (2*embed_dim)
    """
    def __init__(self,
                 *,
                 dim: int,
                 ch_mult: tuple[int] = (1, 2, 4, 8),
                 num_res_blocks: int,
                 attn_layers: list[int] = [],
                 down_layers: list[int] = [],
                 resamp_with_conv: bool = True,
                 in_dim: int,
                 embed_dim: int,
                 double_z: bool = True,
                 kernel_size: int = 3,
                 clip_act: float = 256.0):
        super().__init__()
        self.dim = dim
        self.num_layers = len(ch_mult)
        self.num_res_blocks = num_res_blocks
        self.in_channels = in_dim
        self.clip_act = clip_act
        self.down_layers = down_layers
        self.attn_layers = attn_layers
        self.conv_in = nn.Conv1d(in_dim, self.dim, kernel_size=kernel_size, padding=kernel_size // 2)

        in_ch_mult = (1, ) + tuple(ch_mult)
        self.in_ch_mult = in_ch_mult

        # 下采样层级
        self.down = nn.ModuleList()
        for i_level in range(self.num_layers):
            block = nn.ModuleList()
            attn = nn.ModuleList()
            block_in = dim * in_ch_mult[i_level]
            block_out = dim * ch_mult[i_level]
            for i_block in range(self.num_res_blocks):
                block.append(
                    ResnetBlock1D(in_dim=block_in,
                                  out_dim=block_out,
                                  kernel_size=kernel_size,
                                  use_norm=True))
                block_in = block_out
                if i_level in attn_layers:
                    attn.append(AttnBlock1D(block_in))
            down = nn.Module()
            down.block = block
            down.attn = attn
            if i_level in down_layers:
                down.downsample = Downsample1D(block_in, resamp_with_conv)
            self.down.append(down)

        # 中间层
        self.mid = nn.Module()
        self.mid.block_1 = ResnetBlock1D(in_dim=block_in,
                                         out_dim=block_in,
                                         kernel_size=kernel_size,
                                         use_norm=True)
        self.mid.attn_1 = AttnBlock1D(block_in)
        self.mid.block_2 = ResnetBlock1D(in_dim=block_in,
                                         out_dim=block_in,
                                         kernel_size=kernel_size,
                                         use_norm=True)

        # 输出: 2*embed_dim (mean + logvar)
        self.conv_out = nn.Conv1d(block_in,
                                  2 * embed_dim if double_z else embed_dim,
                                  kernel_size=kernel_size,
                                  padding=kernel_size // 2)

        self.learnable_gain = nn.Parameter(torch.zeros([]))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # 下采样
        hs = [self.conv_in(x)]
        for i_level in range(self.num_layers):
            for i_block in range(self.num_res_blocks):
                h = self.down[i_level].block[i_block](hs[-1])
                if len(self.down[i_level].attn) > 0:
                    h = self.down[i_level].attn[i_block](h)
                h = h.clamp(-self.clip_act, self.clip_act)
                hs.append(h)
            if i_level in self.down_layers:
                hs.append(self.down[i_level].downsample(hs[-1]))

        # 中间
        h = hs[-1]
        h = self.mid.block_1(h)
        h = self.mid.attn_1(h)
        h = self.mid.block_2(h)
        h = h.clamp(-self.clip_act, self.clip_act)

        # 输出
        h = nonlinearity(h)
        h = self.conv_out(h) * (self.learnable_gain + 1)  # 学习式增益
        return h


# ============================================================
# 解码器
# ============================================================

class Decoder1D(nn.Module):
    """
    1D VAE 解码器，与编码器对称。

    结构:
        conv_in → mid: ResBlock → Attn → ResBlock
                 → [Level 2: ResBlock×3 → Attn]
                 → [Level 1: ResBlock×3]
                 → [Level 0: ResBlock×3 → Attn → Upsample]
                 → conv_out
    """
    def __init__(self,
                 *,
                 dim: int,
                 out_dim: int,
                 ch_mult: tuple[int] = (1, 2, 4, 8),
                 num_res_blocks: int,
                 attn_layers: list[int] = [],
                 down_layers: list[int] = [],
                 kernel_size: int = 3,
                 resamp_with_conv: bool = True,
                 in_dim: int,
                 embed_dim: int,
                 clip_act: float = 256.0):
        super().__init__()
        self.ch = dim
        self.num_layers = len(ch_mult)
        self.num_res_blocks = num_res_blocks
        self.in_channels = in_dim
        self.clip_act = clip_act
        self.down_layers = [i + 1 for i in down_layers]  # 每个下采样层增加一级

        block_in = dim * ch_mult[self.num_layers - 1]

        self.conv_in = nn.Conv1d(embed_dim, block_in, kernel_size=kernel_size, padding=kernel_size // 2)

        # 中间层
        self.mid = nn.Module()
        self.mid.block_1 = ResnetBlock1D(in_dim=block_in, out_dim=block_in, use_norm=True)
        self.mid.attn_1 = AttnBlock1D(block_in)
        self.mid.block_2 = ResnetBlock1D(in_dim=block_in, out_dim=block_in, use_norm=True)

        # 上采样层级
        self.up = nn.ModuleList()
        for i_level in reversed(range(self.num_layers)):
            block = nn.ModuleList()
            attn = nn.ModuleList()
            block_out = dim * ch_mult[i_level]
            for i_block in range(num_res_blocks + 1):
                block.append(ResnetBlock1D(in_dim=block_in, out_dim=block_out, use_norm=True))
                block_in = block_out
                if i_level in attn_layers:
                    attn.append(AttnBlock1D(block_in))
            up = nn.Module()
            up.block = block
            up.attn = attn
            if i_level in self.down_layers:
                up.upsample = Upsample1D(block_in, resamp_with_conv)
            self.up.insert(0, up)

        self.conv_out = nn.Conv1d(block_in, out_dim, kernel_size=kernel_size, padding=kernel_size // 2)
        self.learnable_gain = nn.Parameter(torch.zeros([]))

    def forward(self, z: torch.Tensor) -> torch.Tensor:
        h = self.conv_in(z)

        # 中间
        h = self.mid.block_1(h)
        h = self.mid.attn_1(h)
        h = self.mid.block_2(h)
        h = h.clamp(-self.clip_act, self.clip_act)

        # 上采样
        for i_level in reversed(range(self.num_layers)):
            for i_block in range(self.num_res_blocks + 1):
                h = self.up[i_level].block[i_block](h)
                if len(self.up[i_level].attn) > 0:
                    h = self.up[i_level].attn[i_block](h)
                h = h.clamp(-self.clip_act, self.clip_act)
            if i_level in self.down_layers:
                h = self.up[i_level].upsample(h)

        h = nonlinearity(h)
        h = self.conv_out(h) * (self.learnable_gain + 1)
        return h


# ============================================================
# AutoEncoderModule (VAE + Vocoder 包装)
# ============================================================

class AutoEncoderModule(nn.Module):
    """
    VAE + Vocoder 完整包装类，用于扩散模型流水线。

    流程:
        波形 → mel_converter → 梅尔谱 → VAE.encode → z (潜在)
        z → VAE.decode → 梅尔谱 → vocoder → 波形

    Vocoder 选项:
        - 16k: BigVGAN
        - 44k: BigVGANv2
    """
    def __init__(
        self,
        *,
        vae_ckpt_path: str,
        vocoder_ckpt_path: Optional[str] = None,
        mode: str = '16k',
        need_vae_encoder: bool = True
    ):
        super().__init__()
        if mode == '16k':
            self.vae = VAE(data_dim=80, embed_dim=20, hidden_dim=384).eval()
        elif mode == '44k':
            self.vae = VAE(data_dim=128, embed_dim=40, hidden_dim=512).eval()
        else:
            raise ValueError(f'Unknown mode: {mode}')

        vae_state_dict = torch.load(vae_ckpt_path, weights_only=True, map_location='cpu')
        self.vae.load_state_dict(vae_state_dict)

        for param in self.parameters():
            param.requires_grad = False

        if not need_vae_encoder:
            del self.vae.encoder

    @torch.inference_mode()
    def encode(self, x: torch.Tensor) -> DiagonalGaussianDistribution:
        """梅尔谱 → 潜在高斯分布"""
        return self.vae.encode(x)

    @torch.inference_mode()
    def decode(self, z: torch.Tensor) -> torch.Tensor:
        """潜在表示 → 重建梅尔谱"""
        return self.vae.decode(z)


# ============================================================
# 预设配置
# ============================================================

def VAE_16k(**kwargs) -> VAE:
    """16kHz 配置: 80维梅尔谱, 20维潜在, 384隐藏"""
    return VAE(data_dim=80, embed_dim=20, hidden_dim=384, **kwargs)


def VAE_44k(**kwargs) -> VAE:
    """44kHz 配置: 128维梅尔谱, 40维潜在, 512隐藏"""
    return VAE(data_dim=128, embed_dim=40, hidden_dim=512, **kwargs)


def get_my_vae(name: str, **kwargs) -> VAE:
    if name == '16k':
        return VAE_16k(**kwargs)
    if name == '44k':
        return VAE_44k(**kwargs)
    raise ValueError(f'Unknown model: {name}')
